// === Ambil data harga dari Yahoo Finance ===
const data = items[0].json.chart?.result?.[0];
if (!data) {
  return [{ json: { error: "❌ Tidak ada data dari Yahoo Finance." } }];
}

const closes = data.indicators.quote[0].close.filter(v => v !== null);

// === Fungsi bantu ===
function SMA(data, period) {
  return data.map((_, i, arr) => {
    if (i < period) return null;
    const slice = arr.slice(i - period, i);
    return slice.reduce((a, b) => a + b, 0) / period;
  });
}

function RSI(data, period = 14) {
  let gains = [], losses = [];
  for (let i = 1; i < data.length; i++) {
    const diff = data[i] - data[i - 1];
    gains.push(diff > 0 ? diff : 0);
    losses.push(diff < 0 ? -diff : 0);
  }

  if (gains.length < period) return null;

  let avgGain = gains.slice(0, period).reduce((a, b) => a + b, 0) / period;
  let avgLoss = losses.slice(0, period).reduce((a, b) => a + b, 0) / period;

  for (let i = period; i < gains.length; i++) {
    avgGain = (avgGain * (period - 1) + gains[i]) / period;
    avgLoss = (avgLoss * (period - 1) + losses[i]) / period;
  }

  const rs = avgGain / (avgLoss || 1);
  return 100 - 100 / (1 + rs);
}

// === Hitung indikator ===
const ma50 = SMA(closes, 50);
const ma200 = SMA(closes, 200);

const lastClose = closes.at(-1);
const lastMA50 = ma50.at(-1);
const lastMA200 = ma200.filter(v => v !== null).at(-1) || lastMA50;
const rsi = RSI(closes, 14);

// === Tentukan sinyal ===
let signal = "⚪ Tidak ada sinyal saat ini";
if (rsi && rsi < 30) signal = "🔵 RSI Oversold (Potensi Buy)";
else if (rsi && rsi > 70) signal = "🔴 RSI Overbought (Potensi Sell)";
else if (lastMA50 > lastMA200) signal = "🟢 Golden Cross (Buy Signal)";
else if (lastMA50 < lastMA200) signal = "🔻 Death Cross (Sell Signal)";

// === Return hasil ===
return [{
  json: {
    symbol: data.meta.symbol || "BTC-USD",
    lastClose,
    rsi: rsi ? rsi.toFixed(2) : null,
    ma50: lastMA50 ? lastMA50.toFixed(2) : null,
    ma200: lastMA200 ? lastMA200.toFixed(2) : null,
    signal
  }
}];

// Ambil semua item hasil Merge
const results = items.map(item => item.json);

console.log("Jumlah item masuk:", results.length);

// Helper Function SMA
function SMA(data, period) {
  return data.map((_, i, arr) => {
    if (i < period) return null;

    const slice = arr.slice(i - period, i);

    return (
      slice.reduce((a, b) => a + b, 0) / period
    );
  });
}

// Helper Function RSI
function RSI(data, period = 14) {

  const gains = [];
  const losses = [];

  for (let i = 1; i < data.length; i++) {

    const diff = data[i] - data[i - 1];

    gains.push(diff > 0 ? diff : 0);
    losses.push(diff < 0 ? -diff : 0);

  }

  if (gains.length < period) return null;

  let avgGain =
    gains.slice(0, period)
      .reduce((a, b) => a + b, 0) / period;

  let avgLoss =
    losses.slice(0, period)
      .reduce((a, b) => a + b, 0) / period;

  for (let i = period; i < gains.length; i++) {

    avgGain =
      ((avgGain * (period - 1)) + gains[i]) /
      period;

    avgLoss =
      ((avgLoss * (period - 1)) + losses[i]) /
      period;

  }

  const rs = avgGain / (avgLoss || 1);

  return 100 - (100 / (1 + rs));
}

const output = [];

for (const data of results) {

  try {

    const result =
      data.chart?.result?.[0];

    if (!result) {

      output.push({
        json: {
          error: "Chart result tidak ditemukan"
        }
      });

      continue;
    }

    const symbol =
      result.meta?.symbol || "UNKNOWN";

    console.log("Memproses:", symbol);

    const closesRaw =
      result.indicators?.quote?.[0]?.close || [];

    const closes =
      closesRaw.filter(
        v => v !== null && v !== undefined
      );

    console.log(
      symbol,
      "jumlah candle:",
      closes.length
    );

    if (closes.length < 14) {

      output.push({
        json: {
          symbol,
          error: "Data tidak cukup"
        }
      });

      continue;
    }

    const lastClose =
      closes[closes.length - 1];

    const rsi =
      RSI(closes, 14);

    let lastMA50 = null;
    let lastMA200 = null;

    if (closes.length >= 50) {

      const ma50 =
        SMA(closes, 50);

      lastMA50 =
        ma50.filter(v => v !== null).at(-1);
    }

    if (closes.length >= 200) {

      const ma200 =
        SMA(closes, 200);

      lastMA200 =
        ma200.filter(v => v !== null).at(-1);
    }

    let signal =
      "⚪ Tidak ada sinyal saat ini";

    if (rsi !== null && rsi < 30) {

      signal =
        "🔵 RSI Oversold (Potensi Buy)";

    } else if (rsi !== null && rsi > 70) {

      signal =
        "🔴 RSI Overbought (Potensi Sell)";

    } else if (
      lastMA50 !== null &&
      lastMA200 !== null &&
      lastMA50 > lastMA200
    ) {

      signal =
        "🟢 Golden Cross (Buy Signal)";

    } else if (
      lastMA50 !== null &&
      lastMA200 !== null &&
      lastMA50 < lastMA200
    ) {

      signal =
        "🔻 Death Cross (Sell Signal)";
    }

    output.push({
      json: {
        symbol,
        lastClose: Number(lastClose.toFixed(2)),
        rsi: rsi ? Number(rsi.toFixed(2)) : null,
        ma50: lastMA50
          ? Number(lastMA50.toFixed(2))
          : null,
        ma200: lastMA200
          ? Number(lastMA200.toFixed(2))
          : null,
        signal
      }
    });

  } catch (error) {

    output.push({
      json: {
        error: error.message
      }
    });

  }
}

console.log(
  "Jumlah output:",
  output.length
);

return output;

